import { describe, expect, it } from 'vitest'
import {
  AvailabilityState,
  availabilityState,
  calculateAvailabilityMessage,
  convertToEventAvailability,
} from '@/api/events'
import type { RawEventCounter } from '@/types'

const counter = (fields: Partial<RawEventCounter>): RawEventCounter => ({
  id: 'evt-1',
  max_subscribers: 10,
  subscribers: 0,
  waiting_list: 0,
  max_waiting_list: 5,
  ...fields,
})

describe('convertToEventAvailability — producer sentinel + phase switch', () => {
  const cases: Array<{
    name: string
    input: RawEventCounter
    expectedSlots: number
    expectedWaitingList: boolean
    expectedState: AvailabilityState
    expectedMessage: string
  }> = [
    {
      name: 'Unlimited event (max_subscribers === -1): sentinel -1, subscriber phase',
      input: counter({ max_subscribers: -1, subscribers: 999 }),
      expectedSlots: -1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Unlimited,
      expectedMessage: 'Freie Plätze verfügbar',
    },
    {
      name: 'Subscribers open, many slots remaining',
      input: counter({ max_subscribers: 10, subscribers: 2 }),
      expectedSlots: 8,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Subscribing,
      expectedMessage: 'Noch 8 freie Plätze',
    },
    {
      name: 'Subscribers open, exactly one slot remaining (singular message)',
      input: counter({ max_subscribers: 10, subscribers: 9 }),
      expectedSlots: 1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Subscribing,
      expectedMessage: 'Noch 1 freier Platz',
    },
    {
      name: 'Subscribers full, waiting-list open: phase switches, isWaitingList true',
      input: counter({ max_subscribers: 10, subscribers: 10, max_waiting_list: 5, waiting_list: 1 }),
      expectedSlots: 4,
      expectedWaitingList: true,
      expectedState: AvailabilityState.WaitingList,
      expectedMessage: 'Warteliste ist geöffnet',
    },
    {
      name: 'Subscribers and waiting-list full: 0 + isWaitingList true (FullyBooked)',
      input: counter({ max_subscribers: 10, subscribers: 10, max_waiting_list: 5, waiting_list: 5 }),
      expectedSlots: 0,
      expectedWaitingList: true,
      expectedState: AvailabilityState.FullyBooked,
      expectedMessage: 'Ausgebucht',
    },
    {
      name: 'Unlimited event ignores the waiting-list phase entirely',
      input: counter({ max_subscribers: -1, subscribers: 999, max_waiting_list: 0, waiting_list: 0 }),
      expectedSlots: -1,
      expectedWaitingList: false,
      expectedState: AvailabilityState.Unlimited,
      expectedMessage: 'Freie Plätze verfügbar',
    },
    {
      name: 'Subscribers exactly at capacity but waiting-list open does NOT underflow below zero',
      input: counter({
        max_subscribers: 10,
        subscribers: 12,
        max_waiting_list: 3,
        waiting_list: 0,
      }),
      expectedSlots: 3,
      expectedWaitingList: true,
      expectedState: AvailabilityState.WaitingList,
      expectedMessage: 'Warteliste ist geöffnet',
    },
    {
      name: 'Negative phantom: subscribers exceed cap and waiting-list exceeds cap clamps to 0',
      input: counter({
        max_subscribers: 10,
        subscribers: 15,
        max_waiting_list: 4,
        waiting_list: 9,
      }),
      expectedSlots: 0,
      expectedWaitingList: true,
      expectedState: AvailabilityState.FullyBooked,
      expectedMessage: 'Ausgebucht',
    },
  ]

  for (const c of cases) {
    it(c.name, () => {
      const av = convertToEventAvailability(c.input)
      expect(av.availableSlots).toBe(c.expectedSlots)
      expect(av.isWaitingList).toBe(c.expectedWaitingList)
      expect(av.message).toBe(c.expectedMessage)
      expect(availabilityState(av)).toBe(c.expectedState)
    })
  }
})

describe('availabilityState — sentinel + phase decode (the one canonical read site)', () => {
  const cases: Array<{
    name: string
    slots: number
    waiting: boolean
    expected: AvailabilityState
  }> = [
    { name: 'sentinel -1 ⇒ Unlimited regardless of isWaitingList (well-formed input)', slots: -1, waiting: false, expected: AvailabilityState.Unlimited },
    { name: 'subscriber phase, slots remaining ⇒ Subscribing', slots: 5, waiting: false, expected: AvailabilityState.Subscribing },
    { name: 'subscriber phase, exactly one slot ⇒ Subscribing', slots: 1, waiting: false, expected: AvailabilityState.Subscribing },
    { name: 'waiting-list phase, slots remaining ⇒ WaitingList', slots: 3, waiting: true, expected: AvailabilityState.WaitingList },
    { name: 'waiting-list phase, exactly one slot ⇒ WaitingList', slots: 1, waiting: true, expected: AvailabilityState.WaitingList },
    { name: 'waiting-list phase, zero slots ⇒ FullyBooked', slots: 0, waiting: true, expected: AvailabilityState.FullyBooked },
    { name: 'subscriber phase, zero slots ⇒ FullyBooked (unreachable in producer but defensive)', slots: 0, waiting: false, expected: AvailabilityState.FullyBooked },
  ]

  for (const c of cases) {
    it(c.name, () => {
      expect(availabilityState({ availableSlots: c.slots, isWaitingList: c.waiting })).toBe(c.expected)
    })
  }
})

describe('calculateAvailabilityMessage — message derives through the state predicate', () => {
  const cases: Array<[number, boolean, string]> = [
    [-1, false, 'Freie Plätze verfügbar'],
    [5, false, 'Noch 5 freie Plätze'],
    [1, false, 'Noch 1 freier Platz'],
    [3, true, 'Warteliste ist geöffnet'],
    [1, true, 'Warteliste ist geöffnet'],
    [0, true, 'Ausgebucht'],
    [0, false, 'Ausgebucht'],
  ]

  for (const [slots, waiting, expected] of cases) {
    it(`slots=${slots}, isWaitingList=${waiting} ⇒ "${expected}"`, () => {
      expect(calculateAvailabilityMessage(slots, waiting)).toBe(expected)
    })
  }
})

describe('-1 contract — the sentinel appears only in producer + predicate, never in messages', () => {
  it('Unlimited never produces a "Noch N" or "Ausgebucht" message', () => {
    expect(calculateAvailabilityMessage(-1, false)).toBe('Freie Plätze verfügbar')
    expect(calculateAvailabilityMessage(-1, true)).toBe('Freie Plätze verfügbar')
  })

  it('the predicate is the only function reading === -1 besides the producer', () => {
    const src = availabilityState.toString()
    expect(src).toContain('=== -1')
  })
})

